#pragma once

// ── Automations ───────────────────────────────────────────────────────────────
// Scenes, automations, scripts and toggles the Automations screen can run.
// Generated by the configurator; one entry per row there.

struct AutomationEntity {
  const char* name;        // display name (list row / card)
  const char* entity_id;   // Home Assistant entity_id
  const char* service;     // HA service to call
  int         room;        // 1-based into ROOM_LIST (room_entities.h), 0 = no room
  const char* icon;        // Material Symbols codepoint (UTF-8) for the card,
                           // listed in the automation_icon font glyphs (26 px)
};

static const AutomationEntity AUTOMATION_LIST[] = {
  { "Boost Heat", "automation.boost_heat",   "automation.trigger", 3, "\uea05" },  // local_fire_department
  { "Eco Mode",   "automation.eco_mode",     "automation.trigger", 0, "\uea35" },  // eco
  { "Lock Door",  "script.lock_front_door",  "script.turn_on",     0, "\ue88d" },  // lock
  { "Arm Alarm",  "script.arm_alarm",        "script.turn_on",     0, "\ue32a" },  // security
  { "Good Night", "scene.good_night",        "scene.turn_on",      3, "\uef44" },  // bedtime
  { "Movie Time", "scene.movie_time",        "scene.turn_on",      2, "\ue02c" },  // movie
  { "Start Work", "scene.start_work",        "scene.turn_on",      1, "\ue8f9" },  // work
  { "Vacuum",     "script.vacuum_living",    "script.turn_on",     2, "\uf0ff" },  // cleaning_services
};
// Physical array length (always >= 1). Static per-entity arrays in the
// controllers are sized with this, never with the count.
static const int AUTOMATION_LIST_CAPACITY = sizeof(AUTOMATION_LIST) / sizeof(AUTOMATION_LIST[0]);
// Number of CONFIGURED entries; may be 0. Index wrapping goes through
// wrap_index() in display_utils.h, which is defined for a count of 0.
static const int AUTOMATION_LIST_COUNT = sizeof(AUTOMATION_LIST) / sizeof(AUTOMATION_LIST[0]);

// ── Shortcut keys ─────────────────────────────────────────────────────────────
// The automations on the left / right round keys of the Automations screen.
// A key with index -1 has no shortcut and its button isn't drawn.
struct AutomationShortcut {
  int         index;  // into AUTOMATION_LIST, -1 = none
  const char* label;  // up to 5 chars, "" = icon only
  const char* icon;   // Material Symbols codepoint (UTF-8) for the button,
                      // listed in the shortcut_icon font glyphs; nullptr = label
                      // only (a key needs a label, an icon or both)
};

static const AutomationShortcut AUTOMATION_SHORTCUT_L = { 4, "NIGHT", "\uef44" };  // Good Night
static const AutomationShortcut AUTOMATION_SHORTCUT_R = { 5, "",      "\ue02c" };  // Movie Time, icon only
